def closure(edges):
    out = {}
    for x, y in edges:
        out.setdefault(x, set()).add(y)
    reach = set(edges)
    frontier = set(edges)
    while frontier:
        new = set()
        for x, y in frontier:
            for z in out.get(y, ()):
                if (x, z) not in reach:
                    new.add((x, z))
        reach |= new
        frontier = new
    return reach
